# Adaptive rejection sampling after Gilks and Wild (1992).

check.sample.count <- function(n) {
  if (missing(n) || is.null(n) || length(n) != 1) {
    stop("sample count must be a single number")
  }
  if (is.na(n) || !is.finite(n) || n < 1 || n != floor(n)) {
    stop("sample count must be a positive integer")
  }
  n
}

check.domain <- function(domain) {
  if (is.null(domain) || length(domain) != 2 || any(is.na(domain))) {
    stop("domain must be a vector of two endpoints")
  }
  if (is.finite(domain[1]) && is.finite(domain[2]) && domain[1] >= domain[2]) {
    stop("lower endpoint of domain must be less than upper endpoint")
  }
  domain
}

log.of.density <- function(f, x) {
  out <- f(x)
  if (any(out > 1) || any(out < 0)) {
    stop("density function must return log-scale values or values in 0 to 1")
  }
  out
}

check.log.concavity <- function(x, l) {
  m <- length(x)
  if (m < 3) return(invisible(NULL))
  s <- diff(l) / diff(x)
  if (any(diff(s) > 1e-10)) {
    stop("log of supplied density is not concave")
  }
  invisible(NULL)
}

upper.hull.intercepts <- function(x, l, s) {
  k <- length(x) - 1
  (l[1:k] * x[k + 1] - l[k + 1] * x[1:k] - s[1:k] * x[1:k] * x[k + 1]) /
    (x[k + 1] - x[1:k])
}

lower.hull.intercepts <- function(x, l, s) {
  k <- length(x) - 1
  (l[1:k] * x[k + 1] - l[k + 1] * x[1:k] - s[1:k] * x[1:k] * x[k + 1]) /
    (x[k + 1] - x[1:k])
}

upper.hull.point <- function(x, l, s, z) {
  k <- length(x)
  i <- find.interval(x, z)
  i <- min(max(i, 1), k - 1)
  l[i] + s[i] * (z - x[i])
}

lower.hull.point <- function(x, l, s, z) {
  i <- find.interval(x, z)
  if (i < 1 || i > length(x) - 1) return(-Inf)
  l[i] + s[i] * (z - x[i])
}

find.interval <- function(x, z) {
  if (z <= x[1]) return(0)
  if (z >= x[length(x)]) return(length(x) - 1)
  which.max(x <= z) - 1
}

draw.upper.hull <- function(a, x, l, s, u) {
  k <- length(x) - 1
  c <- upper.hull.intercepts(x, l, s)
  area <- sapply(1:k, function(i) {
    xi <- max(x[i], a[1])
    xj <- min(x[i + 1], a[2])
    if (xj <= xi) return(0)
    exp(l[i]) * (exp(s[i] * (xj - x[i])) - 1) / s[i]
  })
  total <- sum(area)
  if (!is.finite(total) || total <= 0) {
    stop("could not compute total area under the upper hull")
  }
  cut <- u * total
  i <- which(cumsum(area) >= cut)[1]
  y <- l[i] + log((cut - sum(area[1:max(i - 1, 0)])) * s[i] / exp(l[i]) + 1)
  x[i] + (y - l[i]) / s[i]
}

initial.abscissae <- function(f, a, l) {
  x0 <- if (all(is.finite(a))) (a[1] + a[2]) / 2 else 0
  x <- x0 + c(-2, -1, 0, 1, 2)
  x <- x[x >= a[1] & x <= a[2]]
  l <- l(x)
  if (any(!is.finite(l))) {
    d <- max(abs(x - x0), 1)
    while (any(!is.finite(l))) {
      x <- c(x, x0 - d, x0 + d)
      x <- x[x >= a[1] & x <= a[2]]
      l <- l(x)
      d <- d * 2
    }
  }
  ok <- is.finite(l)
  x <- x[ok]
  l <- l[ok]
  ord <- order(x)
  list(x = x[ord], l = l[ord])
