draw.upper.hull <- function(a, x, h, s, u) {
  k <- length(x) - 1
  area <- numeric(k)
  for (i in 1:k) {
    xi <- max(x[i], a[1])
    xj <- min(x[i + 1], a[2])
    if (xj > xi) {
      area[i] <- exp(h[i] + s[i] * xi) * (1 - exp(s[i] * (xi - xj))) / s[i]
    }
  }
  total <- sum(area)
  if (!is.finite(total) || total <= 0) {
    stop("could not compute total area under the upper hull")
  }
  i <- which(cumsum(area) >= u * total)[1]
  part <- u * total - sum(area[1:max(i - 1, 0)])
  x[i] + log(part * s[i] / exp(h[i] + s[i] * x[i]) + 1) / s[i]
